def q_integer(q: float, n: int) -> float:
    if n == 0:
        return 0.0
    return sum(q ** (n - 1 - 2 * k) for k in range(n))

import math
def recover_q(lambda1: float) -> tuple:
    disc = lambda1**2 - 4
    if disc < 0:
        raise ValueError('No real solution')
    s = math.sqrt(disc)
    return ((lambda1 + s) / 2, (lambda1 - s) / 2)

def spectral_count(q: float, T: float) -> int:
    n = 0
    while True:
        qi_n = sum(q**(n-1-2*k) for k in range(n)) if n > 0 else 0
        qi_n1 = sum(q**(n-2*k) for k in range(n+1))
        if qi_n * qi_n1 > T:
            return n
        n += 1
